from werkzeug.security import generate_password_hash, check_password_hash


class User:
    def __init__(self, id, username, password_hash, roles=None):
        self.id = id
        self.username = username
        self.password_hash = password_hash
        self.roles = roles or ["user"]

    def check_password(self, password):
        return check_password_hash(self.password_hash, password)

    def to_dict(self):
        return {
            "id": self.id,
            "username": self.username,
            "roles": self.roles,
        }


_USERS = {
    "admin": User(
        id=1,
        username="admin",
        password_hash=generate_password_hash("admin123"),
        roles=["admin", "user"],
    ),
    "user": User(
        id=2,
        username="user",
        password_hash=generate_password_hash("user123"),
        roles=["user"],
    ),
}


def get_user_by_username(username):
    return _USERS.get(username)


def get_user_by_id(user_id):
    for user in _USERS.values():
        if user.id == user_id:
            return user
    return None

from flask import jsonify


class APIError(Exception):
    def __init__(self, message, status_code=400, details=None):
        super().__init__(message)
        self.message = message
        self.status_code = status_code
        self.details = details or {}


class AuthenticationError(APIError):
    def __init__(self, message="Authentication required", details=None):
        super().__init__(message, status_code=401, details=details)


class ForbiddenError(APIError):
    def __init__(self, message="Forbidden", details=None):
        super().__init__(message, status_code=403, details=details)


class NotFoundError(APIError):
    def __init__(self, message="Resource not found", details=None):
        super().__init__(message, status_code=404, details=details)


class ValidationError(APIError):
    def __init__(self, message="Validation failed", details=None):
        super().__init__(message, status_code=422, details=details)


class RateLimitError(APIError):
    def __init__(self, message="Too many requests", details=None):
        super().__init__(message, status_code=429, details=details)


class ConflictError(APIError):
    def __init__(self, message="Conflict", details=None):
        super().__init__(message, status_code=409, details=details)


def register_error_handlers(app):
    @app.errorhandler(APIError)
    def handle_api_error(error):
        response = {
            "error": {
                "code": error.status_code,
                "message": error.message,
                "details": error.details,
            }
        }
        return jsonify(response), error.status_code

    @app.errorhandler(400)
    def handle_400(error):
        return jsonify({
            "error": {
                "code": 400,
                "message": "Bad request",
                "details": str(error),
            }
        }), 400

    @app.errorhandler(404)
    def handle_404(error):
        return jsonify({
            "error": {
                "code": 404,
                "message": "Not found",
                "details": str(error),
            }
        }), 404

    @app.errorhandler(405)
    def handle_405(error):
        return jsonify({
            "error": {
                "code": 405,
                "message": "Method not allowed",
                "details": str(error),
            }
        }), 405

    @app.errorhandler(429)
    def handle_429(error):
        return jsonify({
            "error": {
                "code": 429,
                "message": "Too many requests",
                "details": str(error),
            }
        }), 429

    @app.errorhandler(500)
    def handle_500(error):
        return jsonify({
            "error": {
                "code": 500,
                "message": "Internal server error",
                "details": str(error) if app.debug else "An unexpected error occurred",
            }
        }), 500

from flask import request, url_for


def parse_pagination_params(default_per_page=20, max_per_page=100):
    page = request.args.get("page", 1, type=int)
    per_page = request.args.get("per_page", default_per_page, type=int)

    if page < 1:
        page = 1
    if per_page < 1:
        per_page = default_per_page
    if per_page > max_per_page:
        per_page = max_per_page

    return page, per_page


def paginate_response(items, total, page, per_page, endpoint, **kwargs):
    last_page = max(1, (total + per_page - 1) // per_page)

    links = {"self": _page_url(endpoint, page, per_page, **kwargs)}

    if page > 1:
        links["first"] = _page_url(endpoint, 1, per_page, **kwargs)
        links["prev"] = _page_url(endpoint, page - 1, per_page, **kwargs)

    if page < last_page:
        links["next"] = _page_url(endpoint, page + 1, per_page, **kwargs)
        links["last"] = _page_url(endpoint, last_page, per_page, **kwargs)

    return {
        "data": items,
        "pagination": {
            "page": page,
            "per_page": per_page,
            "total": total,
            "pages": last_page,
        },
        "links": links,
    }


def _page_url(endpoint, page, per_page, **kwargs):
    if request.host_url is None:
        host = "http://localhost"
    else:
        host = request.host_url.rstrip("/")
    try:
        path = url_for(endpoint, page=page, per_page=per_page, _external=False, **kwargs)
        return host + path
    except Exception:
        return None

from marshmallow import Schema, fields, validate, ValidationError


class LoginSchema(Schema):
    username = fields.String(required=True, validate=validate.Length(min=1, max=128))
